  "glossary": [
    {
      "term": "national referral mechanism",
      "definition": "The UK system for referring people who may have been trafficked or enslaved so authorities can decide whether they are victims and what support they need."
    },
    {
      "term": "reasonable grounds decision",
      "definition": "An early decision on whether there are reasonable grounds to believe someone may be a victim of modern slavery."
    },
    {
      "term": "conclusive grounds decision",
      "definition": "The later decision on whether someone is confirmed to be a victim of modern slavery."
    },
    {
      "term": "ECAT",
      "definition": "The Council of Europe convention that sets requirements for preventing human trafficking and protecting its victims."
    },
    {
      "term": "ECHR",
      "definition": "The European Convention on Human Rights, an agreement that protects basic rights and freedoms."
    },
    {
      "term": "recovery and reflection period",
      "definition": "A period of at least 30 days intended to let a possible trafficking victim recover and consider their options."
    },
    {
      "term": "public order disqualification",
      "definition": "A rule that can exclude some people from protection as trafficking victims on public safety grounds."
    },
    {
      "term": "statutory defence",
      "definition": "A defence in law that may protect victims from conviction for some crimes they were forced to commit because of their exploitation."
    },
    {
      "term": "independent child trafficking guardians",
      "definition": "Independent advocates who help children who may have been trafficked and make sure their needs are heard."
    }
  ]
